-- Import this into MySQL only if you are NOT running Laravel migrations.
CREATE DATABASE IF NOT EXISTS smart_internship CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE smart_internship;
CREATE TABLE companies (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL,industry VARCHAR(120),contact_name VARCHAR(150),email VARCHAR(180),phone VARCHAR(40),address VARCHAR(255),status ENUM('active','inactive') NOT NULL DEFAULT 'active',description TEXT,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL) ENGINE=InnoDB;
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(255) NOT NULL,email VARCHAR(255) NOT NULL UNIQUE,email_verified_at TIMESTAMP NULL,password VARCHAR(255) NOT NULL,phone VARCHAR(40),role ENUM('admin','intern','supervisor') NOT NULL DEFAULT 'intern',status ENUM('active','inactive') NOT NULL DEFAULT 'active',remember_token VARCHAR(100),created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL) ENGINE=InnoDB;
CREATE TABLE programs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NOT NULL,title VARCHAR(180) NOT NULL,department VARCHAR(120),description TEXT,slots INT UNSIGNED NOT NULL DEFAULT 1,start_date DATE NOT NULL,end_date DATE NOT NULL,status ENUM('draft','open','closed') NOT NULL DEFAULT 'draft',created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,CONSTRAINT programs_company_fk FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE registrations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,program_id BIGINT UNSIGNED NOT NULL,intern_id BIGINT UNSIGNED NOT NULL,supervisor_id BIGINT UNSIGNED NULL,status ENUM('pending','approved','rejected','completed') NOT NULL DEFAULT 'pending',applied_at DATE,notes TEXT,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,UNIQUE KEY registration_program_intern_unique(program_id,intern_id),CONSTRAINT registrations_program_fk FOREIGN KEY(program_id) REFERENCES programs(id) ON DELETE CASCADE,CONSTRAINT registrations_intern_fk FOREIGN KEY(intern_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT registrations_supervisor_fk FOREIGN KEY(supervisor_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
